"""
This library contains all O&M related Keywords
"""

from builtins import object
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()

try:
    from taf.ul.trs_e2e_fw.lib.oam.mzoam.mzoam_base import MzoamBaseClass
    from taf.ul.trs_e2e_fw.lib.oam.mzoam.commissioning import Commissioning
    from taf.ul.trs_e2e_fw.lib.oam.mzoam.reset import Reset
    from taf.ul.trs_e2e_fw.lib.oam.mzoam.other_ops import OtherOps
    from taf.ul.trs_e2e_fw.lib.oam.mzoam.alarms import Alarms
except ImportError:
    logger.warn('TAF libraries not available for MzOam operations. Ignore, this msg if the keywords are not used')


class MzoamInterface(object):
    """
    Mzoam interface
    """
    def __init__(self):
        pass

    def setup_oamops(self, **kwargs):
        """
        This keyword is used to Setup OAM operations for Primary BTS, currently using ADMIN.
        If Remote LMP details exist in config data for given dut, it is considered as a chain
        setup.

            | *Arguments* | *Comments* |
            | dut | Default value is 'bts'.  If explicitly passed, the dut will be looked in
            config data |
            | bts_host | Optional argument, BTS IP, Default value is picked from config data,
            can also be explicitly passed, If mplane is the value, mplane IP will be picked
            from SCF |
            | bts_port | Optional argument, ADMIN port, Default value is picked from config data,
            can also be explicitly passed | user | Optional argument, ADMIN username, Default
            value is picked from config data can also be explicitly passed |
            | password | Optional argument, ADMIN password, Default value is picked
            from config data can also be explicitly passed | use_ssl | Optional argument,
            Default value is True |
           | update_interval | Optional argument, Default value is False, Interval in (ms) to see
           updates from ADMIN API | admin_api_log_dir | Optional argument,  Default value is "",
           Path to store
           ADMIN API Log | timeout | Optional argument, Default value is 240 seconds,
           Timeout for connection |
           | alias | Optional argument, Default value is 'default', Name of the execution context |


            *Examples:*

            *Setup OAM operations on bts with default values*
            | Setup Oamops |
            *Setup OAM operations on bts with explicit values*
            | Setup Oamops | bts_port=80 | use_ssl=False | timeout=120 | alias=conn1 |
            *Setup OAM operations on bts via mplane with explicit values*
            | Setup Oamops | bts_host=mplane | bts_port=80 | use_ssl=False | timeout=120 |
            alias=mplaneconn1 |
            *Setup OAM operations on chained bts*
            | Setup Oamops | dut=chained_bts1 | bts_port=80 | use_ssl=False | timeout=120 |
            alias=conn2 |

        """

        MzoamBaseClass().setup_oamops(**kwargs)

    def teardown_oamops(self, **kwargs):
        """
        This keyword will teardown OAM operations and release used resources.

           | *Arguments* | *Comments* |
           | alias | Optional argument | Default value is 'default' | Name of the execution
           context |

            *Examples:*

            *Teardown an ADMIN connection*
            | Teardown Oamops | alias=conn1 |

        """

        MzoamBaseClass().teardown_oamops(**kwargs)

    def perform_commissioning(self, **kwargs):
        """
        This keyword is used to perform recommissioning on a bts.

            | *Arguments* | *Comments* | *Default* |
            | type | Type of recommissioning. Can be delta or param | |
            | delta_file | The path of the delta xml file to be used | mandatory when 'type'
            is 'delta' |
            | skip_parameter_relation_errors | Optional | default is True |
            | rat | The RAT the param belongs to. If it is RAT independent, pass lte |
            mandatory when 'type' is 'param' | param_path | Part of the distname or full
            distname | mandatory when 'type' is 'param' |
            | operation | create, update or delete | mandatory when 'type' is 'param' |
            | value | The value to be applied | mandatory when 'type' is 'param' |
            | timeout | timeout value | default is 300 seconds |
            | alias | Name of the execution context | default |


            *Examples:*

            *Perform Delta type Recommissioning*
            | Perform Recommissioning | type=delta   |  delta_file=sample1.xml |
            skip_parameter_relation_errors=${True} | timeout=300 |
            *Perform Parameter type Recommissioning*
            | Perform Recommissioning | type=param   |  rat=lte  |
            param_path=MPLANENW-1:mPlaneDscp |
            operation=update  |  value=36 | timeout=300 |

        """

        return Commissioning().perform_commissioning(**kwargs)

    def reset(self, **kwargs):
        """
        This keyword performs reset operations
        | *Supported operations* |
        | site |
        | *Arguments* | *Comments* | *Default* |
        | operation | Operation from supported operations list | Mandatory |
        | alias | Name of execution context | |
        """
        return Reset().reset(**kwargs)

    def get_sw_versions(self, **kwargs):
        """
        Function to get software versions
        """
        return MzoamBaseClass().get_sw_versions(**kwargs)

    def collect_snapshot(self, **kwargs):
        """
        Function to collect snapshot
        """
        return OtherOps().collect_snapshot(**kwargs)

    def verify_alarm(self, **kwargs):
        """
        Function to verify alarms
        """
        return Alarms().verify_alarm(**kwargs)
